UPDATE businesses SET description = 'Mopani Pharmacy Monument Park is an independent community pharmacy located in Monument Park Shopping Centre, serving Monument Park and the surrounding area. The pharmacy dispenses prescription and over-the-counter medication, and its pharmacists provide advice on treatment and medicine use. An on-site clinic extends services beyond dispensing, offering vaccinations, pregnancy tests, HIV screening and counselling, and family planning services. The clinic also monitors blood pressure, cholesterol and glucose levels, and conducts Discovery Vitality health screening tests. Medicine delivery is available for patients who are unable to collect prescriptions in person. Mopani Pharmacy Monument Park has been part of the local Monument Park community for more than 30 years, building a long-standing relationship with residents and families who rely on it for everyday health needs. Its combination of dispensing and clinic services makes it a convenient first point of contact for routine healthcare, from managing chronic conditions to preventative screening, without the need to travel to a separate clinic or hospital. The pharmacy continues to operate from its established location within the shopping centre, remaining accessible to the patients and families it has served for decades.', description_enriched_at = datetime('now') WHERE slug = 'mopani-pharmacy-monument-park-pretoria-monument-park' AND description = 'Mopani Pharmacy Monument Park is an independent community pharmacy in Monument Park Shopping Centre offering basic clinic services, immunisations and Discovery Vitality tests alongside prescriptions and over-the-counter medication.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
